package com.quiz.servlet;
import com.quiz.dao.*; import com.quiz.model.*; import java.io.*; import java.sql.SQLException; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/teacher/notifications") public class NotificationServlet extends HttpServlet { private final QuizDAO qd=new QuizDAO();private final NotificationDAO nd=new NotificationDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user");req.setAttribute("quizzes",qd.findByTeacher(u.getId()));req.getRequestDispatcher("/WEB-INF/views/teacher-notifications.jsp").forward(req,resp);}catch(SQLException e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user");int id=Integer.parseInt(req.getParameter("quizId"));String title=req.getParameter("title")==null?"":req.getParameter("title").trim();String msg=req.getParameter("message")==null?"":req.getParameter("message").trim();if(title.isEmpty()||msg.isEmpty()||qd.findByIdAndTeacher(id,u.getId())==null){resp.sendRedirect(req.getContextPath()+"/teacher/notifications?error=1");return;}nd.save(u.getId(),id,title,msg);resp.sendRedirect(req.getContextPath()+"/teacher/notifications?sent=1");}catch(Exception e){throw new ServletException(e);}}}
